func (aq *AttributeQuery) loadValueTexts(ctx context.Context, query *ValueTextQuery, nodes []*Attribute, init func(*Attribute), assign func(*Attribute, *ValueText)) error {
	fks := make([]driver.Value, 0, len(nodes))
	nodeids := make(map[uint64]*Attribute)
	for i := range nodes {
		fks = append(fks, nodes[i].ID)
		nodeids[nodes[i].ID] = nodes[i]
		if init != nil {
			init(nodes[i])
		}
	}
	if len(query.ctx.Fields) > 0 {
		query.ctx.AppendFieldOnce(valuetext.FieldAttrID)
	}
	query.Where(predicate.ValueText(func(s *sql.Selector) {
		s.Where(sql.InValues(s.C(attribute.ValueTextsColumn), fks...))
	}))
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		fk := n.AttrID
		node, ok := nodeids[fk]
		if !ok {
			return fmt.Errorf(`unexpected referenced foreign-key "attr_id" returned %v for node %v`, fk, n.ID)
		}
		assign(node, n)
	}
	return nil
}
